-- Academy: no two read lessons in a row, and a hands-on demo where a real
-- BullPen screen fits. Generated by scripts/academy-apply-staging.ts from
-- content/academy-staging/ after review. Checks are drafted from the read
-- lesson they follow (scripts/academy-interleave-checks.ts); demos are
-- hand-written tours over targets that exist on each surface.

-- ai-research
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'what-is-a-thesis-check', 'Check: What Makes a Good Investment Thesis', 'quiz', 1, 10, $json${"questions":[{"question":"Your friend says: \"I bought this stock because it feels like it's going up.\" Based on the lesson, what does your friend actually have?","options":["A complete investment thesis","A hunch, not a thesis","A catalyst","A written risk analysis"],"correctIndex":1,"explanation":"The lesson says if you can't state your argument in a few sentences, you have a hunch, not a thesis. A feeling about price direction isn't an honest, testable argument."},{"question":"Someone writes up a stock: what the company does, why it will win, and the good news that could prove them right, but leaves out the risks. Why does the lesson warn against this?","options":["Leaving out the risks is how hype masquerades as analysis","A thesis only needs two parts anyway","Risks aren't part of a thesis","It makes the thesis too long"],"correctIndex":0,"explanation":"A good thesis includes catalysts AND risks. Skipping the risks (and the catalysts) is exactly how the lesson says hype gets dressed up as real analysis."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'ai-research'
ON CONFLICT (course_id, slug) DO NOTHING;
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'asking-better-questions-check', 'Check: Asking Better Questions', 'quiz', 3, 10, $json${"questions":[{"question":"You want to use AI to research a company you're considering. Based on the lesson, which question would get you the most useful, actionable answer?","options":["\"Is this a good stock to buy?\"","\"What are the biggest risks to this company's main revenue source?\"","\"Will this stock go up?\"","\"Should I invest my money here?\""],"correctIndex":1,"explanation":"Specific, focused questions earn answers you can act on, while vague ones like \"is this a good buy?\" get vague, hedged replies."},{"question":"The lesson says to \"ask for the bear case on purpose.\" What's the main reason for doing this?","options":["The AI gives longer answers to negative questions","It helps you stress-test your idea instead of just confirming what you already believe","Bad news is more accurate than good news","It's the only way to get the AI to mention risks"],"correctIndex":1,"explanation":"We naturally hunt for reasons we're right, so deliberately asking why you might be wrong tests your thesis instead of just decorating it."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'ai-research'
ON CONFLICT (course_id, slug) DO NOTHING;
UPDATE academy_lessons l SET order_index = v.ord FROM (VALUES ('what-is-a-thesis', 0), ('asking-better-questions', 2), ('sources-and-skepticism', 4), ('ai-research-quiz', 5), ('research-with-ai-demo', 6), ('build-and-defend-thesis', 7)) AS v(slug, ord), academy_courses c
WHERE c.slug = 'ai-research' AND l.course_id = c.id AND l.slug = v.slug;

