-- company-fundamentals
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'revenue-profit-margins-check', 'Check: Revenue, Profit & Margins', 'quiz', 1, 10, $json${"questions":[{"question":"A bakery sells $500 of bread in a week. After paying for flour, rent, and workers, $75 is left over. What is the bakery's profit margin?","options":["75%","15%","25%","42.5%"],"correctIndex":1,"explanation":"Profit margin is net income divided by revenue: $75 ÷ $500 = 15%. It shows you keep 15 cents of every dollar that comes in."},{"question":"Company A earns $800 million in profit with a 4% margin. Company B earns $10 million in profit with a 25% margin. Which company is more efficient at turning sales into profit?","options":["Company A, because it makes far more total profit","Company B, because it keeps more cents out of every dollar of sales","They are equally efficient since both make a profit"],"correctIndex":1,"explanation":"Margin, not raw dollars, measures efficiency. Company B keeps 25 cents per dollar versus Company A's 4 cents, so B turns sales into profit much more efficiently."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'company-fundamentals'
ON CONFLICT (course_id, slug) DO NOTHING;
UPDATE academy_lessons l SET order_index = v.ord FROM (VALUES ('revenue-profit-margins', 0), ('eps-and-pe-ratio', 2), ('fundamentals-quiz', 3), ('fundamentals-match', 4), ('cash-flow-and-debt', 5), ('cheap-or-expensive', 6), ('fundamentals-demo', 7)) AS v(slug, ord), academy_courses c
WHERE c.slug = 'company-fundamentals' AND l.course_id = c.id AND l.slug = v.slug;

-- dividend-investing-deep-dive
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'growth-vs-high-yield-check', 'Check: Dividend Growth vs. High Yield', 'quiz', 1, 10, $json${"questions":[{"question":"A stock pays a 6% dividend yield. If you invest $200, how much do you earn in dividends per year?","options":["$6","$12","$60","$120"],"correctIndex":1,"explanation":"A 6% yield pays $6 for every $100 invested, so $200 earns $12 a year. Yield is simply the yearly payment compared to the price you paid."},{"question":"A stock's price suddenly crashes, and now its dividend yield shows a very high number. According to the lesson, why might this be a warning sign rather than good news?","options":["A high yield always means the company is doing great","The yield rose automatically because the price fell, and the struggling company may cut its dividend later","A crashing price means the dividend will definitely double","High yields are never risky"],"correctIndex":1,"explanation":"When the price drops, the yield goes up on its own even if the business is in trouble. That kind of high yield can be a trap if the dividend gets cut."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'dividend-investing-deep-dive'
ON CONFLICT (course_id, slug) DO NOTHING;
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'reinvest-or-take-cash-check', 'Check: Reinvesting vs. Taking the Cash', 'quiz', 3, 10, $json${"questions":[{"question":"Maya is 30, still working, and doesn't need her dividend money for bills. Based on the lesson's rule of thumb, what should she probably do?","options":["Take the cash and spend it right away","Reinvest the dividends to buy more shares","Sell all her shares to avoid dividends","Stop investing until she retires"],"correctIndex":1,"explanation":"Maya is in her growth phase and doesn't need the income, so reinvesting lets the snowball effect and compounding do the heavy lifting over time."},{"question":"The lesson calls reinvesting a 'snowball effect.' Why does that snowball keep growing?","options":["The company raises its dividend every single year","New shares bought with dividends pay their own dividends, which buy even more shares","Cash dividends gain interest while sitting in your account","The stock price is guaranteed to rise each year"],"correctIndex":1,"explanation":"That's compounding: your dividends buy more shares, those shares pay their own dividends, and your money starts earning money too."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'dividend-investing-deep-dive'
ON CONFLICT (course_id, slug) DO NOTHING;
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'growth-vs-yield-demo', 'Growers vs. High Yield, Projected', 'demo', 6, 25, $json${"surface":"dividend-calculator","years":15,"holdings":[{"ticker":"SCHD","name":"Schwab US Dividend ETF","mode":"amount","value":"10,000"},{"ticker":"JNJ","name":"Johnson & Johnson","mode":"amount","value":"5,000"},{"ticker":"O","name":"Realty Income","mode":"amount","value":"5,000"}],"steps":[{"id":"intro","target":"dividend-holdings","requiredAction":"none","title":"Growers and a yielder","body":"This mix holds steady dividend growers next to a higher-yield payer. The higher yield pays more today. The growers raise their payout each year. Let's see what that difference does over time."},{"id":"settings","target":"dividend-settings","requiredAction":"none","title":"15 years, reinvested","body":"The projection runs 15 years with dividends reinvested, so each payout buys more shares. Time is where dividend growth shows up, so the window is longer than usual."},{"id":"calculate","target":"dividend-calculate","requiredAction":"run-calculation","title":"Run it","body":"Click Calculate dividends to project the income using each holding's real dividend history."},{"id":"results","target":"dividend-results","requiredAction":"none","title":"Watch the income climb","body":"Look at how the yearly income grows, not just where it starts. A rising payout plus reinvestment is how income outgrows a bigger starting yield."},{"id":"wrap","target":"none","requiredAction":"none","title":"Yield today, growth tomorrow","body":"Neither kind is always better. Ask whether a payout can keep growing, not just how big it is today. Try swapping holdings to test your own mix."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'dividend-investing-deep-dive'
ON CONFLICT (course_id, slug) DO NOTHING;
UPDATE academy_lessons l SET order_index = v.ord FROM (VALUES ('growth-vs-high-yield', 0), ('reinvest-or-take-cash', 2), ('resilient-income-portfolio', 4), ('dividend-investing-quiz', 5), ('the-yield-looks-amazing', 7)) AS v(slug, ord), academy_courses c
WHERE c.slug = 'dividend-investing-deep-dive' AND l.course_id = c.id AND l.slug = v.slug;

