INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'whats-in-an-earnings-report-check', 'Check: What''s Actually in an Earnings Report', 'quiz', 1, 10, $json${"questions":[{"question":"A company reports strong profits for the past three months, but its stock price falls right after. Based on the lesson, what's the most likely reason?","options":["Its guidance for the future looked weak","The SEC rejected the report","It skipped the management commentary section","Profits don't affect stock prices at all"],"correctIndex":0,"explanation":"Stock prices move on the future, not just the past. Great past results can be outweighed by weak guidance, which is the company's own forecast for what's coming next."},{"question":"A CEO writes a note explaining that sales grew because a new product sold well, but shipping costs hurt profits. Which part of the earnings report is this?","options":["The results","Guidance","Management commentary","The SEC filing requirement"],"correctIndex":2,"explanation":"Management commentary is where leaders explain the numbers in plain words: what went well, what struggled, and why. It's the story behind the spreadsheet."}]}$json$::jsonb
