INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'we-already-read-it-for-you-check', 'Check: You Don''t Have to Read the Filing Yourself', 'quiz', 3, 10, $json${"questions":[{"question":"Your friend owns a stock and says, \"The company just reported, but I don't want to read that huge legal document.\" Based on the lesson, what should you tell her?","options":["She has to read the full filing to understand the results","BullPen reads the filing and shows the key numbers like Revenue and Net Income for her","Nobody can understand company results without a finance degree","She should just ignore the report completely"],"correctIndex":1,"explanation":"The lesson's main point is that BullPen pulls the numbers that matter out of the filing, so you get the highlights without reading the dense document yourself."},{"question":"The lesson suggests a real-life habit for when a company you own reports its results. What is it?","options":["Immediately buy more shares before reading anything","Open the stock page and read the key fundamentals and the Why Today note before reacting","Wait a year before checking how the company did","Call the company directly to ask about the numbers"],"correctIndex":1,"explanation":"The lesson's homework is to skim the key fundamentals and read the plain-English Why Today note first, so you stay informed and avoid reacting without context."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'earnings-reports-calls'
