SELECT id, 'news-without-the-filing-demo', 'Get the Story Without the Filing', 'demo', 6, 25, $json${"surface":"ai-research","fixtureId":"nvda-why-today","steps":[{"id":"intro","target":"ai-ask","requiredAction":"none","title":"Start from the move","body":"Earnings, guidance and analyst calls are what usually move a stock. Here's a stock that moved today. Instead of opening a 100-page filing, let's ask what happened."},{"id":"ask","target":"ai-ask","requiredAction":"run-research","title":"Ask why it moved","body":"Click to ask. BullPen reads the day's news and explains the move in plain language."},{"id":"answer","target":"ai-answer","requiredAction":"none","title":"Look forward, not back","body":"Notice what drove it: signals about future demand and an analyst's outlook. That is the same lesson as guidance in an earnings report. The market cares most about what comes next."},{"id":"sources","target":"ai-sources","requiredAction":"none","title":"Then check the source","body":"Every claim links to where it came from. Open one when a number matters to your decision. That's the part of the filing worth reading."},{"id":"wrap","target":"none","requiredAction":"none","title":"Earnings day, handled","body":"Next time a company you own reports, open its stock page and ask why it moved. Results tell you what happened. Guidance tells you why the price reacted."}]}$json$::jsonb
