SELECT id, 'the-three-statements-check', 'Check: The Three Statements', 'quiz', 1, 10, $json${"questions":[{"question":"A company wants to know exactly what it owns and what it owes on December 31st. Which statement should it look at?","options":["The income statement","The balance sheet","The cash flow statement"],"correctIndex":1,"explanation":"The balance sheet is a snapshot at a single moment showing total assets on one side and debts on the other, which is exactly what this question asks."},{"question":"A business reports a healthy profit on paper, but its managers are worried there isn't enough actual money in the bank. Which statement best helps them see the real cash moving in and out?","options":["The cash flow statement","The income statement","The balance sheet"],"correctIndex":0,"explanation":"The cash flow statement exists precisely because profit on paper and cash in the bank are not the same thing. Operating Cash Flow tracks the real money moving in and out."}]}$json$::jsonb
