INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'the-income-statement-check', 'Check: The Income Statement', 'quiz', 3, 10, $json${"questions":[{"question":"A company has $1,000 in revenue and $600 in direct costs to make its product. What is its gross profit, and its gross margin?","options":["$600 gross profit, 60% gross margin","$400 gross profit, 40% gross margin","$400 gross profit, 60% gross margin","$1,000 gross profit, 100% gross margin"],"correctIndex":1,"explanation":"Gross profit is revenue minus direct costs ($1,000 - $600 = $400), and gross margin is that divided by revenue ($400 / $1,000 = 40%)."},{"question":"Which figure shows profit from the core business before interest and taxes are removed?","options":["Revenue","Gross Profit","Operating Income","Net Income"],"correctIndex":2,"explanation":"Operating Income is what's left after subtracting the costs of running the business, but before interest and taxes, so it's often the cleanest read on whether the business itself works."}]}$json$::jsonb
