SELECT id, 'currency-exposure-adrs-check', 'Check: Currency Exposure & ADRs', 'quiz', 3, 10, $json${"questions":[{"question":"You buy a German company's stock and it rises 8% in euros. During that same time, the euro loses 8% of its value against the US dollar. What is the likely result when you convert back to dollars?","options":["A gain of about 16%, because both numbers add together","A gain close to zero, because the currency drop cancels out the stock's rise","A guaranteed loss of 8%, no matter what the stock did","A gain of exactly 8%, because the currency never matters"],"correctIndex":1,"explanation":"When the foreign currency weakens by about the same amount the stock rises, the two roughly cancel out, leaving your dollar gain near zero. That's the hidden currency variable at work."},{"question":"A friend says: \"I bought an ADR, so I don't have to worry about currency moving my return at all.\" Based on the lesson, is that right?","options":["Yes, ADRs are priced in dollars so currency no longer affects you","No, the currency variable is still baked into the ADR's price in the background","Yes, ADRs remove all foreign risk including the stock's performance","No, ADRs can only be bought using foreign currency"],"correctIndex":1,"explanation":"An ADR lets you buy in US dollars on a US exchange, but the foreign currency's movement is still built into its price. The convenience doesn't erase the currency risk."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'international-crypto-deep-dive'
