-- investing-psychology
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'why-your-brain-fights-you-check', 'Check: Why Your Brain Fights You', 'quiz', 1, 10, $json${"questions":[{"question":"Maria owns two stocks. One has dropped a lot since she bought it, and one has climbed nicely. Based on the lesson, which mistake is she most likely to make?","options":["Sell the climbing stock too early and hold the dropping stock too long","Sell the dropping stock quickly and hold the climbing stock forever","Buy more of both stocks right away","Ignore both stocks and never check them again"],"correctIndex":0,"explanation":"The lesson calls this 'snip our flowers and water our weeds': we lock in gains too soon on winners and cling to losers to avoid admitting a real loss."},{"question":"The lesson says losing $100 hurts about twice as much as gaining $100 feels good. What does this tell us about ourselves?","options":["We feel the pain of losses more strongly than the joy of equal gains","We feel gains and losses with exactly equal intensity","Most people never feel anything about money","Gains feel twice as good as losses feel bad"],"correctIndex":0,"explanation":"This lopsided feeling is called loss aversion: the sting of a loss is roughly double the pleasure of an equal gain, which nudges us toward avoiding losses at all costs."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'investing-psychology'
ON CONFLICT (course_id, slug) DO NOTHING;
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'crowd-mood-demo', 'Feel the Crowd''s Mood, Live', 'demo', 5, 25, $json${"surface":"market-mood","steps":[{"id":"intro","target":"none","requiredAction":"none","title":"The crowd has a mood","body":"Every bias in this course is something a whole market can feel at once. This is BullPen's real Market Mood tool. It turns that crowd feeling into a number you can actually look at."},{"id":"score","target":"mood-hero","requiredAction":"none","title":"Fear and greed, scored","body":"0 is extreme fear, 100 is extreme greed. When this sits near the top, FOMO is everywhere and \"everyone is buying it\" feels true. That is exactly when your own judgment matters most."},{"id":"momentum","target":"mood-signal-s-p-500-momentum","requiredAction":"none","title":"Recency bias, in one signal","body":"This compares the S&P 500 to its 125-day average. After a long run up, it feels like prices can only keep rising. That feeling is recency bias: the recent past standing in for the future."},{"id":"safe-haven","target":"mood-signal-safe-haven-demand","requiredAction":"none","title":"Loss aversion, in one signal","body":"When investors rush from stocks into safer bonds, this swings toward fear. Losses feel worse than gains feel good, so selling in a panic can feel safe even when it locks in the loss."},{"id":"wrap","target":"none","requiredAction":"none","title":"Check the mood, then decide","body":"You can't switch your biases off, but you can notice when the crowd is pulling hardest. A glance at this before a big decision is a simple way to ask whether it's you deciding, or the mood."}]}$json$::jsonb
