SELECT id, 'stocks-dont-move-alone-check', 'Check: Stocks Don''t Move Alone', 'quiz', 1, 10, $json${"questions":[{"question":"A company reports surprisingly strong earnings, and its stock jumps while competitors barely move. Which kind of catalyst is this?","options":["A macro catalyst, because it affects the whole market","A company-specific catalyst, because it happened to that one business","An interest rate decision","A jobs report"],"correctIndex":1,"explanation":"Earnings reports happen to one business, so they explain why a single stock moves while its competitors stay put. That's the company-specific bucket."},{"question":"Your stock dropped today, and you notice nearly every other stock dropped too after the Fed signaled higher rates. What's the most likely explanation?","options":["Something is specifically wrong with your company","The whole market moved together because of a macro event","Your company launched a bad product","Your company changed its leadership"],"correctIndex":1,"explanation":"When the whole market falls on Fed news, a healthy stock can drop just because it's part of that ocean. Checking if everything moved together saves you from a false alarm."}]}$json$::jsonb
