SELECT id, 'yield-curve-and-credit-spreads-check', 'Check: Reading the Yield Curve & Credit Spreads', 'quiz', 3, 10, $json${"questions":[{"question":"A 3-month government bond is paying more than a 10-year government bond. According to the lesson, what is this called, and what does it often hint at?","options":["A normal yield curve, hinting the economy is healthy","A yield curve inversion, often watched as a possible recession warning","A credit spread, meaning company bonds got riskier","A rate hike, meaning the Fed just raised interest rates"],"correctIndex":1,"explanation":"When short-term yields climb above long-term ones, the line flips upside down. That inversion is one of the more closely watched warning signs of a possible recession, though it is a signal, not a promise."},{"question":"Investors suddenly get nervous and demand a much bigger reward to hold risky company bonds instead of safe government bonds. What happens to the credit spread?","options":["It widens, because people want more reward for taking on risk","It shrinks, because risky bonds became safer","It disappears, because government bonds stop paying","It stays the same, since spreads never change"],"correctIndex":0,"explanation":"A credit spread is the extra yield demanded for riskier company bonds. When people get nervous, that gap widens because they want more reward for the added risk."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'macro-mechanics'
ON CONFLICT (course_id, slug) DO NOTHING;
