INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'what-options-are-check', 'Check: What Options Actually Are', 'quiz', 1, 10, $json${"questions":[{"question":"Your friend buys an option that gives her the right to buy a stock at $50. But when the deadline comes, the stock is doing poorly and she doesn't want it. What can she do?","options":["She must buy the stock at $50 anyway","She can simply walk away and not buy it","She is forced to sell the stock instead","She has to pay an extra fee to avoid buying"],"correctIndex":1,"explanation":"An option is a right, not an obligation. Just like a deposit on a house, you can choose to walk away if you change your mind."},{"question":"You want the right to sell a stock at a set price. Which flavor of option do you need?","options":["A call, because it lets you buy","A put, because it lets you sell","Either one works the same way","Neither, options only let you buy"],"correctIndex":1,"explanation":"A put gives you the right to sell. The memory trick: you put something away from you (sell), while you call something toward you (buy)."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'options-basics'
ON CONFLICT (course_id, slug) DO NOTHING;
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'asymmetric-risk-check', 'Check: Why Options Risk Is Asymmetric', 'quiz', 3, 10, $json${"questions":[{"question":"You pay a $200 premium to buy an option. The bet goes wrong and the option expires worthless. How much do you lose?","options":["$200, the premium you paid","More than $200, because losses can grow","Nothing, since it expired","It depends on how far the stock fell"],"correctIndex":0,"explanation":"For a buyer, the premium is the most you can lose. If the option expires worthless, you simply lose what you paid, in this case $200."},{"question":"Why is selling (writing) an option described as having the more dangerous side of this uneven risk?","options":["The seller pays a premium they can never get back","The seller's possible losses can be far larger than the premium they collected","The seller is guaranteed to lose money every time","The seller cannot collect any money upfront"],"correctIndex":1,"explanation":"The seller collects the premium but takes on an obligation to complete the trade, which can lead to losses many times bigger than the premium received."}]}$json$::jsonb
