ON CONFLICT (course_id, slug) DO NOTHING;
INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT id, 'pe-in-depth-check', 'Check: The P/E Ratio in Depth', 'quiz', 3, 10, $json${"questions":[{"question":"A company trades at a P/E of 25. What does that tell you in plain English?","options":["You pay $25 for every $1 of the company's yearly profit","The company earns $25 for every share you buy","The stock price will rise 25% this year","You pay $1 for every $25 of the company's profit"],"correctIndex":0,"explanation":"P/E is price divided by earnings per share, so a P/E of 25 means $25 of price for each $1 of annual profit."},{"question":"A software firm has a P/E of 38 and a utility has a P/E of 14. Based on the lesson, what's the best conclusion?","options":["The utility is a better buy because its P/E is lower","The software firm is overpriced and should be avoided","Both can be fair; the higher P/E likely reflects faster expected growth","A P/E above 20 is always too expensive"],"correctIndex":2,"explanation":"There's no single 'good' P/E. Faster-growing companies command higher P/Es, and both can be perfectly fair when judged against their growth and peers."}]}$json$::jsonb
FROM academy_courses WHERE slug = 'valuation'
ON CONFLICT (course_id, slug) DO NOTHING;
UPDATE academy_lessons l SET order_index = v.ord FROM (VALUES ('price-is-not-value', 0), ('pe-in-depth', 2), ('beyond-pe', 4), ('valuation-quiz', 5), ('valuation-match', 6), ('find-undervalued-demo', 7), ('cheap-or-value-trap', 8)) AS v(slug, ord), academy_courses c
WHERE c.slug = 'valuation' AND l.course_id = c.id AND l.slug = v.slug;

-- options-basics: correct the Call, Put and In the Money definitions
UPDATE academy_lessons l SET content = $json${"pairs":[{"term":"Call","definition":"The right to buy a stock at a set price before a set date."},{"term":"Put","definition":"The right to sell a stock at a set price before a set date."},{"term":"Strike Price","definition":"The set price at which you can buy or sell the stock."},{"term":"Premium","definition":"The upfront cost you pay to buy the option."},{"term":"Expiration","definition":"The date when the option ends and stops working."},{"term":"In the Money","definition":"When using the option right now would be worth something, before counting what you paid for it."}]}$json$::jsonb
FROM academy_courses c WHERE c.slug = 'options-basics' AND l.course_id = c.id AND l.type = 'match';
